// PRIVATE authoring corpus. Public sources define topics, not company exam questions.
// Cases, figures and grade rubrics are original proposals awaiting expert calibration.
const grades = ['Intern', 'Junior', 'Middle', 'Senior', 'Lead'];
const rows = [];
function F(group, slug, title, prompt, dimensions, variants, sources, alternatives, errors, practical = true) {
  const levels = Object.fromEntries(grades.map((grade, index) => {
    const [task, actions] = variants[index];
    const answers = actions.split('|');
    if (answers.length !== dimensions.length) throw new Error(`Invalid BusinessAnalysis rubric: ${slug}/${grade}`);
    const criteria = dimensions.map(([skill, , extension], i) => ({
      id: `criterion-${i + 1}`,
      // Shared skill mapping was authored for the Middle action. Other levels
      // need a separate skill review; absence is preferable to false evidence.
      ...(grade === 'Middle' ? { skillId: `BusinessAnalysis:${group}:${skill}` } : {}),
      label: answers[i].replace(/\.$/u, ''),
      missing: `Не рассматривает необходимое действие: ${answers[i]}`,
      partial: `Называет это действие, но не выполняет его полностью или не связывает с условиями задачи: ${answers[i]}`,
      meets: answers[i],
      strong: `${answers[i]} Обосновывает действие на конкретном примере или контрпримере исходного кейса; дополнительно: ${extension}`,
    }));
    return [grade, { task: `${task} Покажите ход решения и границы выводов по условиям кейса.`, expected: answers.join(' '), criteria }];
  }));
  rows.push({ id: `open-business-${slug}`, specialization: 'BusinessAnalysis', group, title, prompt,
    practical, answerFormat: 'text', language: null, sourceIds: sources.map(id => `business-${id}`),
    tags: [slug, group.toLowerCase(), practical ? 'practical-artifact' : 'reasoning'],
    referenceAnswer: levels.Middle.expected, acceptableAlternatives: alternatives, criticalErrors: errors,
    criteria: levels.Middle.criteria, levels,
    personalization: { allowed: ['domain', 'entityNames'], invariants: [
      'Сохранить участников, права, исходные факты, числовые ограничения и границы решения.',
      'Сохранить артефакт задания уровня, критерии, допустимые альтернативы и критические ошибки.',
      'Не добавлять сведения о реальном работодателе или клиенте; заявления опыта не доказывают навык.',
    ] },
  });
}

